// The hooks the Speedometer steps use (window.ssrWorkload). Benchmark mode
// is on unless the page URL has `?realtime`: then the virtual clock is off
// and chat steps play in real time, which is useful for comparing with the
// replayed reference in a normal tab.
import { advance, enableVirtualTime, isVirtualTime } from "../platform/timers";
import { defineRoom, playFrames } from "../platform/fake-irc";
import type { WorkloadData } from "../platform/data";
import { nextEvent } from "./events";
import { whenIdle } from "./idle";

export const benchmarkMode = !new URLSearchParams(location.search).has("realtime");

export interface StreamingSiteWorkload {
  nextEvent: typeof nextEvent;
  whenIdle: typeof whenIdle;
  /** Plays the chat frames of a timeline step and advances the clock by its duration. */
  runTimelineStep(name: string): Promise<void>;
}

declare global {
  interface Window {
    ssrWorkload?: StreamingSiteWorkload;
  }
}

export function setUpBenchmark(data: WorkloadData): void {
  if (benchmarkMode) enableVirtualTime();
  for (const room of data.rooms) defineRoom(room);
  window.ssrWorkload = {
    nextEvent,
    whenIdle,
    async runTimelineStep(name) {
      const step = data.steps.find((s) => s.name === name);
      if (!step) throw new Error(`unknown step ${name}`);
      const frames = data.frames[name];
      if (frames) playFrames(step.channel, frames);
      if (isVirtualTime()) await advance(step.durationMs);
      else await new Promise((resolve) => window.setTimeout(resolve, step.durationMs));
      await whenIdle();
    },
  };
}
