// Serves the GraphQL endpoint from prepared responses. Each batched request
// body is parsed, each operation is answered by its resolver, and the reply
// is a real Response with a JSON text body, so Apollo parses it as it would
// a network response.
import { track } from "../workload/idle";

type Resolver = (variables: Record<string, unknown>) => unknown;

// With ?debug in the URL, the batches served are recorded in window.__gqlBatches.
if (new URLSearchParams(location.search).has("debug")) (globalThis as { __gqlBatches?: unknown[] }).__gqlBatches = [];

const resolvers = new Map<string, Resolver>();

export function registerGqlResolver(operationName: string, resolver: Resolver): void {
  resolvers.set(operationName, resolver);
}

interface Operation {
  operationName: string;
  variables?: Record<string, unknown>;
}

export function fakeGqlFetch(_input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
  const body = JSON.parse(String(init?.body ?? "[]")) as Operation | Operation[];
  const operations = Array.isArray(body) ? body : [body];
  const results = operations.map((op) => {
    const resolver = resolvers.get(op.operationName);
    if (!resolver) return { errors: [{ message: `no resolver for ${op.operationName}` }] };
    return { data: resolver(op.variables ?? {}), extensions: { operationName: op.operationName } };
  });
  const text = JSON.stringify(Array.isArray(body) ? results : results[0]);
  (globalThis as { __gqlBatches?: unknown[] }).__gqlBatches?.push({ ops: operations.map((o) => o.operationName), bytes: text.length });
  return track(Promise.resolve(new Response(text, { status: 200, headers: { "content-type": "application/json" } })));
}
