import { differenceInSeconds, formatDistanceStrict } from "date-fns";
import { now } from "../platform/timers";

const pad = (n: number) => String(n).padStart(2, "0");

/** 24318 becomes "24.3K", 1250000 "1.3M". */
export function compactCount(n: number): string {
  if (n >= 1e6) return `${(n / 1e6).toFixed(n >= 1e7 ? 0 : 1).replace(/\.0$/, "")}M`;
  if (n >= 1e4) return `${(n / 1e3).toFixed(1).replace(/\.0$/, "")}K`;
  return n.toLocaleString("en-US");
}

/** "3:11:07" from a start time, on the app's clock. */
export function uptime(startedAt: string): string {
  const s = Math.max(0, differenceInSeconds(now(), new Date(startedAt)));
  return `${Math.floor(s / 3600)}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`;
}

export function since(date: string): string {
  return formatDistanceStrict(new Date(date), now(), { addSuffix: true });
}

export function thumbnailUrl(template: string, width: number, height: number): string {
  return template.replace("{width}x{height}", `${width}x${height}`);
}
