// The chat event model shared by the IRC connection, the message buffer and
// the chat UI. Events are plain objects, because the chat list serializes
// each of them with JSON.stringify on every render, as Twitch's does.

export enum ChatEventType {
  Message = "message",
  Action = "action",
  Subscription = "subscription",
  Resubscription = "resubscription",
  SubGift = "subgift",
  SubMysteryGift = "submysterygift",
  GiftPaidUpgrade = "giftpaidupgrade",
  Raid = "raid",
  Announcement = "announcement",
  BitsBadgeTier = "bitsbadgetier",
  Ritual = "ritual",
  Notice = "notice",
  Moderation = "moderation",
  ChatCleared = "chatcleared",
  RoomMods = "roommods",
  SlowMode = "slowmode",
  SubsOnlyMode = "subsonlymode",
  FollowersOnlyMode = "followersonlymode",
  EmoteOnlyMode = "emoteonlymode",
  R9KMode = "r9kmode",
  Connected = "connected",
  Disconnected = "disconnected",
  Reconnect = "reconnect",
  LiveSeparator = "liveseparator",
  Welcome = "welcome",
}

export interface BadgeRef {
  setID: string;
  version: string;
}

export interface ChatUser {
  userID: string;
  userLogin: string;
  displayName: string;
  /** Hex colour, from the `color` tag or the fallback palette. */
  color: string;
  /** The display name has non-ASCII characters. */
  isIntl: boolean;
  userType: string;
  isSubscriber: boolean;
  isMod: boolean;
  isVip: boolean;
  isTurbo: boolean;
  isReturningChatter: boolean;
  badges: BadgeRef[];
  /** `badge-info`: set id to a detail such as the subscription month count. */
  badgeDynamicData: Record<string, string>;
}

export interface EmoteRange {
  startIndex: number;
  endIndex: number;
  id: string;
}

export interface AutoModFlag {
  startIndex: number;
  endIndex: number;
  categories: Record<string, number>;
}

export interface ReplyInfo {
  parentMsgId: string;
  parentUid: string;
  parentUserLogin: string;
  parentDisplayName: string;
  parentMessageBody: string;
  threadParentMsgId: string;
  threadParentUserLogin: string;
}

export enum MessagePartType {
  Text = 0,
  Mention = 1,
  Link = 2,
  Emote = 3,
  Cheer = 4,
  ClipLink = 5,
  VideoLink = 6,
  FlaggedSegment = 7,
}

export type MessagePart =
  | { type: MessagePartType.Text; content: string }
  | { type: MessagePartType.Mention; content: { recipient: string; currentUserMentionRelation: number } }
  | { type: MessagePartType.Link; content: { displayText: string; url: string } }
  | { type: MessagePartType.Emote; content: { alt: string; emoteID: string; images: Record<string, string> } }
  | { type: MessagePartType.Cheer; content: { alt: string; amount: number; prefix: string } }
  | { type: MessagePartType.ClipLink; content: { slug: string; url: string } }
  | { type: MessagePartType.VideoLink; content: { videoID: string; url: string } }
  | { type: MessagePartType.FlaggedSegment; content: { categories: Record<string, number>; parts: MessagePart[] } };

export interface ChatMessageEvent {
  type: ChatEventType.Message | ChatEventType.Action;
  id: string;
  channel: string;
  roomID: string;
  timestamp: number;
  user: ChatUser;
  body: string;
  messageParts: MessagePart[];
  emotes: Record<number, EmoteRange>;
  flags: AutoModFlag[];
  bits: number;
  reply: ReplyInfo | null;
  isFirstMsg: boolean;
  msgId: string | null;
  nonce: string | null;
  deleted: boolean;
  banned: boolean;
  isHistorical: boolean;
  isHighlighted: boolean;
  isMentioningCurrentUser: boolean;
}

export interface ChatNoticeEvent {
  type: Exclude<ChatEventType, ChatEventType.Message | ChatEventType.Action>;
  id: string;
  channel: string;
  timestamp: number;
  msgId: string | null;
  systemMessage: string;
  user: ChatUser | null;
  /** The user's own message on a resub or announcement, already tokenized. */
  body: string | null;
  messageParts: MessagePart[] | null;
  params: Record<string, string>;
}

export type ChatEvent = ChatMessageEvent | ChatNoticeEvent;
