// Turns a chat message body into the parts the chat line renders: text,
// emotes, cheers, links, mentions and AutoMod-flagged segments. The shape
// follows Twitch's tokenizer: split into code points with a regex, then build
// words one code point at a time and classify each word.
import { MessagePartType, type AutoModFlag, type EmoteRange, type MessagePart } from "./types";

export interface SessionUser {
  login: string | null;
  displayName: string | null;
}

export interface TokenizeInput {
  body: string;
  emotes: Record<number, EmoteRange>;
  flags: AutoModFlag[];
  bits: number;
}

let readSession: () => SessionUser = () => ({ login: null, displayName: null });

/** Wires the tokenizer to the Redux session, so that mentions of the signed-in user are highlighted. */
export function setSessionReader(reader: () => SessionUser): void {
  readSession = reader;
}

export const MentionRelation = { None: 0, CurrentUser: 1 } as const;

const CODE_POINT = /[^\uD800-\uDFFF]|[\uD800-\uDBFF][\uDC00-\uDFFF]|[\uD800-\uDFFF]/g;
const WHITESPACE = /\s/;
const PUNCTUATION = /[.,!?;:]/;
const CHEER = /^([a-z]+)(\d+)$/i;
const CLIP_URL = /^(?:https?:\/\/)?(?:clips\.twitch\.tv\/|(?:www\.|m\.)?twitch\.tv\/[\w-]+\/clip\/)([\w-]+)(?:[/?#]\S*)?$/i;
const VIDEO_URL = /^(?:https?:\/\/)?(?:www\.|m\.)?twitch\.tv\/videos\/(\d+)(?:[/?#]\S*)?$/i;
const LINK = /^(https?:\/\/)?((?:[a-z0-9][a-z0-9-]*\.)+[a-z]{2,10})(?::\d{1,5})?(\/[\w./#%&@()+=:?~-]*[\w/#%&@()+=~-])?\/?$/i;
const MENTION = /^([^\w@]*)@(\w{1,25})/;

const CHEER_PREFIXES: Record<string, boolean> = {
  cheer: true,
  doodlecheer: true,
  biblethump: true,
  cheerwhal: true,
  corgo: true,
  party: true,
  scoops: true,
  shamrock: true,
  uni: true,
};

interface Segment {
  start: number;
  end: number;
  categories: Record<string, number> | null;
}

function mergeFlags(flags: AutoModFlag[]): AutoModFlag[] {
  const sorted = flags.slice().sort((a, b) => a.startIndex - b.startIndex);
  const merged: AutoModFlag[] = [];
  for (const flag of sorted) {
    const last = merged[merged.length - 1];
    if (last && flag.startIndex <= last.endIndex + 1) {
      last.endIndex = Math.max(last.endIndex, flag.endIndex);
      for (const key of Object.keys(flag.categories)) {
        last.categories[key] = Math.max(last.categories[key] || 0, flag.categories[key]);
      }
    } else {
      merged.push({ startIndex: flag.startIndex, endIndex: flag.endIndex, categories: { ...flag.categories } });
    }
  }
  return merged;
}

function buildSegments(length: number, flags: AutoModFlag[]): Segment[] {
  const segments: Segment[] = [];
  let cursor = 0;
  for (const flag of mergeFlags(flags)) {
    if (flag.startIndex >= length) break;
    if (flag.startIndex > cursor) segments.push({ start: cursor, end: flag.startIndex - 1, categories: null });
    const end = Math.min(flag.endIndex, length - 1);
    segments.push({ start: flag.startIndex, end, categories: flag.categories });
    cursor = end + 1;
  }
  if (cursor < length) segments.push({ start: cursor, end: length - 1, categories: null });
  return segments;
}

function emoteImages(id: string): Record<string, string> {
  const base = `data/assets/emotes/${id}/`;
  return { "1x": `${base}1.png`, "2x": `${base}2.png`, "4x": `${base}3.png` };
}

function textPart(content: string): MessagePart {
  return { type: MessagePartType.Text, content };
}

function withTrailing(part: MessagePart, trailing: string): MessagePart[] {
  return trailing ? [part, textPart(trailing)] : [part];
}

function wordToParts(
  word: string,
  position: number,
  emotes: Record<number, EmoteRange>,
  bits: number,
  session: SessionUser,
): MessagePart[] {
  const length = word.length;
  if (Object.prototype.hasOwnProperty.call(emotes, position)) {
    return [{ type: MessagePartType.Emote, content: { alt: word, emoteID: emotes[position].id, images: emoteImages(emotes[position].id) } }];
  }

  const cheer = CHEER.exec(word);
  if (cheer && bits > 0 && CHEER_PREFIXES[cheer[1].toLowerCase()] === true) {
    return [{ type: MessagePartType.Cheer, content: { alt: word, amount: parseInt(cheer[2], 10), prefix: cheer[1] } }];
  }

  if (length > 3 && word.indexOf(".") !== -1) {
    let end = length;
    while (end > 0 && PUNCTUATION.test(word.charAt(end - 1))) end--;
    const candidate = word.slice(0, end);
    const trailing = word.slice(end);
    const clip = CLIP_URL.exec(candidate);
    if (clip) return withTrailing({ type: MessagePartType.ClipLink, content: { slug: clip[1], url: candidate } }, trailing);
    const video = VIDEO_URL.exec(candidate);
    if (video) return withTrailing({ type: MessagePartType.VideoLink, content: { videoID: video[1], url: candidate } }, trailing);
    const link = LINK.exec(candidate);
    if (link) {
      const url = link[1] ? candidate : `https://${candidate}`;
      return withTrailing({ type: MessagePartType.Link, content: { displayText: candidate, url } }, trailing);
    }
  }

  const mention = word.indexOf("@") !== -1 ? MENTION.exec(word) : null;
  if (mention) {
    const parts: MessagePart[] = [];
    const recipient = mention[2];
    const lower = recipient.toLowerCase();
    const relation =
      (session.login !== null && lower === session.login.toLowerCase()) ||
      (session.displayName !== null && lower === session.displayName.toLowerCase())
        ? MentionRelation.CurrentUser
        : MentionRelation.None;
    if (mention[1]) parts.push(textPart(mention[1]));
    parts.push({ type: MessagePartType.Mention, content: { recipient, currentUserMentionRelation: relation } });
    const rest = word.slice(mention[0].length);
    if (rest) parts.push(textPart(rest));
    return parts;
  }

  return [textPart(word)];
}

interface Accumulator {
  parts: MessagePart[];
  word: string;
  wordStart: number;
  gap: string;
}

function tokenizeRun(points: string[], offset: number, emotes: Record<number, EmoteRange>, bits: number, session: SessionUser): MessagePart[] {
  const finishWord = (acc: Accumulator): void => {
    if (!acc.word) return;
    if (acc.gap) acc.parts.push(textPart(acc.gap));
    acc.gap = "";
    for (const part of wordToParts(acc.word, acc.wordStart, emotes, bits, session)) acc.parts.push(part);
    acc.word = "";
  };

  const result = points.reduce<Accumulator>(
    (acc, ch, index) => {
      if (WHITESPACE.test(ch)) {
        finishWord(acc);
        acc.gap += ch;
        return acc;
      }
      if (!acc.word) acc.wordStart = offset + index;
      acc.word += ch;
      const next = points[index + 1];
      const nextIsPunctuation = next !== undefined && PUNCTUATION.test(next);
      if (nextIsPunctuation && acc.word.charAt(0) === "@") {
        const after = points[index + 2];
        if (after === undefined || WHITESPACE.test(after)) finishWord(acc);
      }
      return acc;
    },
    { parts: [], word: "", wordStart: offset, gap: "" },
  );
  finishWord(result);
  if (result.gap) result.parts.push(textPart(result.gap));
  return mergeTextParts(result.parts);
}

function mergeTextParts(parts: MessagePart[]): MessagePart[] {
  const merged: MessagePart[] = [];
  for (const part of parts) {
    const last = merged[merged.length - 1];
    if (part.type === MessagePartType.Text && last && last.type === MessagePartType.Text) {
      merged[merged.length - 1] = textPart(last.content + part.content);
    } else {
      merged.push(part);
    }
  }
  return merged;
}

export function tokenize(input: TokenizeInput): MessagePart[] {
  const points = input.body.match(CODE_POINT) ?? [];
  const session = readSession();
  const segments = buildSegments(points.length, input.flags);
  const parts: MessagePart[] = [];
  for (const segment of segments) {
    const run = tokenizeRun(points.slice(segment.start, segment.end + 1), segment.start, input.emotes, input.bits, session);
    if (segment.categories) {
      parts.push({ type: MessagePartType.FlaggedSegment, content: { categories: segment.categories, parts: run } });
    } else {
      for (const part of run) parts.push(part);
    }
  }
  return mergeTextParts(parts);
}

export function mentionsUser(parts: MessagePart[]): boolean {
  return parts.some((part) => {
    if (part.type === MessagePartType.Mention) return part.content.currentUserMentionRelation === MentionRelation.CurrentUser;
    if (part.type === MessagePartType.FlaggedSegment) return mentionsUser(part.content.parts);
    return false;
  });
}
