import { lazy, Suspense } from "react";
import { createBrowserRouter, createMemoryRouter, RouterProvider } from "react-router-dom";
import { HomePage } from "./home/HomePage";
import { Shell } from "./shell/Shell";
import { loadFeatureStyles } from "./features";
import { track } from "./workload/idle";

const loadChannelPage = () => import(/* webpackChunkName: "channel-page" */ "./channel/ChannelPage");
const ChannelPage = lazy(loadChannelPage);
// Fetched during prepare, so that opening a channel does not wait for the chunk.
void track(loadChannelPage());
void track(loadFeatureStyles());

const routes = [
  {
    element: <Shell />,
    children: [
      { path: "/", element: <HomePage /> },
      {
        path: "/:login",
        element: (
          <Suspense fallback={null}>
            <ChannelPage />
          </Suspense>
        ),
      },
    ],
  },
];

// The workload is served from a path inside the Speedometer checkout, so
// in-app URLs live in a memory history unless the page runs at the root.
const router = location.pathname === "/" ? createBrowserRouter(routes) : createMemoryRouter(routes, { initialEntries: ["/"] });

export function App() {
  return <RouterProvider router={router} />;
}
