// Issues the operations that real pages send in the background (analytics
// context, player and chat configuration, community features) and that no
// visible component here renders. Their documents are generated from the
// captured schema. The operations of one page load come in stages, as in
// the capture: a stage starts when the previous one has been answered, and
// all queries of a stage are mounted together, so Apollo batches them.
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { gql, useQuery, type DocumentNode } from "@apollo/client";
import { UI_OPERATIONS } from "../apollo/documents";
import { roomIdFor } from "../apollo/page-resolvers";
import { workloadData } from "../platform/data";

const parsed = new Map<string, DocumentNode>();

function documentFor(name: string): DocumentNode | null {
  let doc = parsed.get(name);
  if (!doc) {
    const source = workloadData().gql.documents[name];
    if (!source) return null;
    doc = gql(source.query);
    parsed.set(name, doc);
  }
  return doc;
}

function variablesFor(name: string, login: string): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const v of workloadData().gql.documents[name]?.variables ?? []) {
    if (v === "channelID" || v === "channelOwnerID") out[v] = roomIdFor(login);
    else if (v === "channelIDs") out[v] = [roomIdFor(login)];
    else out[v] = login;
  }
  return out;
}

const BackgroundQuery = memo(function BackgroundQuery({ name, login, onDone }: { name: string; login: string; onDone: (name: string) => void }) {
  const doc = documentFor(name)!;
  const variables = useMemo(() => variablesFor(name, login), [name, login]);
  const { loading } = useQuery(doc, { variables });
  useEffect(() => {
    if (!loading) onDone(name);
  }, [loading, name, onDone]);
  return null;
});

const STAGE_STARTS = [0, 2, 4, 6];

function stagesFor(waves: string[][]): string[][] {
  const stages = STAGE_STARTS.map((start, i) => {
    const end = STAGE_STARTS[i + 1] ?? waves.length;
    const names = new Set<string>();
    for (const wave of waves.slice(start, end)) for (const n of wave) if (!UI_OPERATIONS.has(n) && documentFor(n)) names.add(n);
    return [...names];
  });
  return stages.filter((s) => s.length > 0);
}

export function BackgroundQueries({ login, context }: { login: string; context: "home" | "home-to-channel" | "channel-to-channel" }) {
  const stages = useMemo(() => stagesFor(workloadData().gql.waves[context]), [context]);
  const [stage, setStage] = useState(0);
  const done = useRef(new Set<string>());
  const onDone = useCallback(
    (name: string) => {
      done.current.add(name);
      if (stages[stage]?.every((n) => done.current.has(n))) setStage((s) => s + 1);
    },
    [stage, stages],
  );
  return (
    <>
      {stages.slice(0, stage + 1).flatMap((names) => names.map((name) => <BackgroundQuery key={name} name={name} login={login} onDone={onDone} />))}
    </>
  );
}
