import { Link } from "react-router-dom";
import { Helmet } from "react-helmet";
import { graphql, type ChildDataProps } from "@apollo/client/react/hoc";
import { SHELVES } from "../apollo/documents";
import { setPageChannel } from "../apollo/page-resolvers";
import { BackgroundQueries } from "../shell/BackgroundQueries";
import { compactCount, thumbnailUrl } from "../shell/format";
import { t } from "../shell/i18n";
import { Avatar, CoreImage, CoreText, Layout } from "../shell/primitives";
import "../styles/home.css";

interface StreamNode {
  __typename: "Stream";
  id: string;
  viewersCount: number;
  previewImageURL: string;
  broadcaster: { login: string; displayName: string; profileImageURL: string; broadcastSettings: { title: string } };
  game: { name: string };
  freeformTags: { id: string; name: string }[];
}

interface GameNode {
  __typename: "Game";
  id: string;
  name: string;
  boxArtURL: string;
  viewersCount: number;
  categorySlug?: string;
}

interface ShelvesData {
  shelves: { edges: { node: { id: string; title: { fallbackLocalizedTitle: string }; content: { edges: { node: StreamNode | GameNode }[] } } }[] };
}

type Props = ChildDataProps<object, ShelvesData, Record<string, unknown>>;

function StreamCard({ stream }: { stream: StreamNode }) {
  const { login, displayName, profileImageURL, broadcastSettings } = stream.broadcaster;
  return (
    <Layout as="article" className="stream-card" data-a-target="stream-card">
      <Link className="stream-card__thumb tw-link-plain" to={`/${login}`} data-a-target="preview-card-image-link">
        <CoreImage src={thumbnailUrl(stream.previewImageURL, 440, 248)} alt={broadcastSettings.title} loading="lazy" />
        <Layout className="stream-card__tag stream-card__tag--live" as="span">
          LIVE
        </Layout>
        <Layout className="stream-card__tag stream-card__tag--viewers" as="span">
          {t("viewers.count", { count: stream.viewersCount })}
        </Layout>
      </Link>
      <Layout className="stream-card__meta">
        <Avatar src={profileImageURL} size={40} alt={displayName} />
        <Layout minWidth="0">
          <CoreText fontSize={4} bold lines={2}>
            {broadcastSettings.title}
          </CoreText>
          <Link to={`/${login}`} className="tw-link-plain">
            <CoreText fontSize={3} color="text-alt-2" ellipsis>
              {displayName}
            </CoreText>
          </Link>
          <CoreText fontSize={3} color="text-alt-2" ellipsis>
            {stream.game.name}
          </CoreText>
          <Layout display="flex" gap={0.5} flexWrap="wrap" margin={{ top: 0.5 }}>
            {stream.freeformTags.slice(0, 2).map((tag) => (
              <Layout key={tag.id} className="channel-tag" as="span">
                {tag.name}
              </Layout>
            ))}
          </Layout>
        </Layout>
      </Layout>
    </Layout>
  );
}

function CategoryCard({ game }: { game: GameNode }) {
  return (
    <Layout as="article" className="category-card" data-a-target="category-card">
      <Link className="category-card__art tw-link-plain" to={`/directory/category/${game.categorySlug ?? game.id}`}>
        <CoreImage src={game.boxArtURL} alt={game.name} loading="lazy" />
      </Link>
      <Layout margin={{ top: 0.5 }}>
        <CoreText fontSize={4} bold ellipsis>
          {game.name}
        </CoreText>
        <CoreText fontSize={3} color="text-alt-2">
          {t("home.viewersOnCategory", { count: game.viewersCount })}
        </CoreText>
      </Layout>
    </Layout>
  );
}

function Shelves({ data }: Props) {
  const shelves = data.shelves?.edges ?? [];
  return (
    <>
      {shelves.map(({ node }) => (
        <Layout as="section" className="shelf" key={node.id} data-a-target="shelf">
          <Layout className="shelf__header">
            <CoreText as="h2" fontSize={6} bold>
              {node.title.fallbackLocalizedTitle}
            </CoreText>
          </Layout>
          <Layout className="shelf__row">
            {node.content.edges.map(({ node: item }, i) => (item.__typename === "Game" ? <CategoryCard key={`${item.id}-${i}`} game={item} /> : <StreamCard key={`${item.id}-${i}`} stream={item} />))}
          </Layout>
        </Layout>
      ))}
    </>
  );
}

const ShelvesWithData = graphql<object, ShelvesData, Record<string, unknown>, Props>(SHELVES, {
  options: () => ({
    variables: { imageWidth: 50, itemsPerRow: 6, platform: "web", limit: 3, requestID: "JIRA-VXP-2397", context: "front_page" },
  }),
})(Shelves as never) as unknown as React.ComponentType;

export function HomePage() {
  setPageChannel("lumenfall");
  return (
    <Layout className="home-page" data-a-target="home-page">
      <Helmet>
        <title>{t("home.title")}</title>
      </Helmet>
      <Link className="home-hero tw-link-plain" to="/lumenfall" data-a-target="home-channel-link">
        <CoreImage className="home-hero__image" src="data/assets/thumbs/lumenfall-1280x360.png" alt="Lumenfall" />
        <Layout className="home-hero__meta">
          <CoreText fontSize={6} bold>
            Lumenfall
          </CoreText>
          <CoreText fontSize={4} color="text-alt">
            {t("viewers.live", { count: 24318 })}
          </CoreText>
        </Layout>
      </Link>
      <ShelvesWithData />
      <BackgroundQueries login="lumenfall" context="home" />
    </Layout>
  );
}
