// The Redux store for session and UI state, with thunks, as on Twitch.
import { applyMiddleware, combineReducers, createStore, type AnyAction } from "redux";
import thunk from "redux-thunk";
import { ui } from "./ui-slice";

export interface SessionState {
  login: string | null;
  displayName: string | null;
}

export interface ChatSettingsState {
  showTimestamps: boolean;
  highContrastUsernames: boolean;
  animatedEmotes: boolean;
  theme: "dark" | "light";
}

function session(state: SessionState = { login: null, displayName: null }, _action: AnyAction): SessionState {
  return state;
}

function chatSettings(
  state: ChatSettingsState = { showTimestamps: false, highContrastUsernames: false, animatedEmotes: true, theme: "dark" },
  _action: AnyAction,
): ChatSettingsState {
  return state;
}

export interface ChatRoomState {
  pauseSetting: "mouseover" | "altkey" | "scroll";
  isPaused: boolean;
  pauseCount: number;
  replyTargetId: string | null;
}

export const chatPausedChanged = (isPaused: boolean) => ({ type: "chat/pausedChanged" as const, isPaused });
export const chatReplyTargetSet = (id: string | null) => ({ type: "chat/replyTargetSet" as const, id });

function chatRoom(
  state: ChatRoomState = { pauseSetting: "mouseover", isPaused: false, pauseCount: 0, replyTargetId: null },
  action: AnyAction,
): ChatRoomState {
  switch (action.type) {
    case "chat/pausedChanged":
      return { ...state, isPaused: action.isPaused, pauseCount: state.pauseCount + (action.isPaused ? 1 : 0) };
    case "chat/replyTargetSet":
      return { ...state, replyTargetId: action.id };
    default:
      return state;
  }
}

const rootReducer = combineReducers({ session, chatSettings, chatRoom, ui });

export type RootState = ReturnType<typeof rootReducer>;

export function createAppStore() {
  return createStore(rootReducer, applyMiddleware(thunk));
}

export type AppStore = ReturnType<typeof createAppStore>;
