// Apollo Client as Twitch configures it: a batching HTTP link to the GraphQL
// endpoint and an InMemoryCache. In the workload the link's fetch is served
// from prepared responses (fake-gql.ts), so Apollo's batching, response
// parsing and cache writes run for real.
import { ApolloClient, ApolloLink, InMemoryCache, Observable, from } from "@apollo/client";
import { track } from "../workload/idle";
import { BatchHttpLink } from "@apollo/client/link/batch-http";
import { fakeGqlFetch } from "./fake-gql";
import { ChatHighlightSettings } from "./line-documents";
import { withGeneratedPolicies } from "./type-policies";
import { workloadData } from "../platform/data";

// Marks every operation as pending from the moment it starts, so the benchmark
// does not see an idle gap while BatchHttpLink waits to fill a batch.
const trackLink = new ApolloLink(
  (operation, forward) =>
    new Observable((observer) => {
      let done: () => void = () => {};
      void track(new Promise<void>((resolve) => (done = resolve)));
      const sub = forward(operation).subscribe({
        next: (v) => observer.next(v),
        error: (e) => {
          observer.error(e);
          done();
        },
        complete: () => {
          observer.complete();
          done();
        },
      });
      return () => {
        sub.unsubscribe();
        done();
      };
    }),
);

let current: ApolloClient<object> | null = null;

/** The client created by the page, for code outside React such as the message buffer. */
export function getApolloClient(): ApolloClient<object> | null {
  return current;
}

export function createApolloClient(): ApolloClient<object> {
  const c = new ApolloClient({
    link: from([trackLink, new BatchHttpLink({ uri: "https://gql.streamingsite.test/gql", fetch: fakeGqlFetch, batchMax: 30, batchInterval: 0 })]),
    cache: new InMemoryCache({ typePolicies: withGeneratedPolicies(workloadData().gql.policies) }),
    assumeImmutableResults: true,
  });
  c.writeQuery({ query: ChatHighlightSettings, data: { currentUser: null } });
  current = c;
  return c;
}
