// The workload's prepared data: generated IRC frames, catalogs and GraphQL
// responses. All of it is fetched before the app starts, so no step waits
// for the network.
import timeline from "../../../data/timeline.json";
import type { ScheduledFrame, RoomInfo } from "./fake-irc";
import { registerPageResolvers } from "../apollo/page-resolvers";

export interface TimelineStep {
  name: string;
  channel: string;
  durationMs: number;
  rate: number;
  mix: string | null;
}

export interface GqlData {
  /** Per file ("global" and one per channel login): operation name to response data. */
  files: Record<string, Record<string, unknown>>;
  documents: Record<string, { query: string; variables: string[] }>;
  waves: Record<"home" | "home-to-channel" | "channel-to-channel", string[][]>;
  policies: Record<string, string[]>;
}

export interface WorkloadData {
  steps: TimelineStep[];
  rooms: RoomInfo[];
  frames: Record<string, ScheduledFrame[]>;
  badges: Record<string, Record<string, { title: string }>>;
  emotes: Record<string, string>;
  gql: GqlData;
}

let data: WorkloadData | null = null;

async function fetchJSON<T>(path: string): Promise<T> {
  const response = await fetch(new URL(`data/${path}`, document.baseURI));
  if (!response.ok) throw new Error(`${path}: ${response.status}`);
  return response.json() as Promise<T>;
}

export async function loadWorkloadData(): Promise<WorkloadData> {
  const steps = timeline.steps as TimelineStep[];
  const chatSteps = steps.filter((s) => s.rate > 0);
  const channels = Object.keys(timeline.channels);
  const [rooms, badges, emotes, gqlGlobal, documents, waves, policies, ...rest] = await Promise.all([
    fetchJSON<RoomInfo[]>("irc/rooms.json"),
    fetchJSON<WorkloadData["badges"]>("catalog/badges.json"),
    fetchJSON<WorkloadData["emotes"]>("catalog/emotes.json"),
    fetchJSON<Record<string, unknown>>("gql/global.json"),
    fetchJSON<GqlData["documents"]>("gql/documents.json"),
    fetchJSON<GqlData["waves"]>("gql/waves.json"),
    fetchJSON<GqlData["policies"]>("gql/policies.json"),
    ...chatSteps.map((s) => fetchJSON<ScheduledFrame[]>(`irc/${s.name}.json`)),
  ]);
  const frames = rest.slice(0, chatSteps.length) as ScheduledFrame[][];
  const channelFiles = (await Promise.all(channels.map((c) => fetchJSON<Record<string, unknown>>(`gql/${c}.json`)))) as Record<string, unknown>[];
  const files: GqlData["files"] = { global: gqlGlobal };
  channels.forEach((c, i) => (files[c] = channelFiles[i]));
  data = {
    steps,
    rooms,
    badges,
    emotes,
    frames: Object.fromEntries(chatSteps.map((s, i) => [s.name, frames[i]])),
    gql: { files, documents, waves, policies },
  };
  registerPageResolvers(data.gql);
  return data;
}

export function workloadData(): WorkloadData {
  if (!data) throw new Error("workload data not loaded");
  return data;
}
