import { createRoot } from "react-dom/client";
import { ApolloProvider } from "@apollo/client";
import { Provider as ReduxProvider } from "react-redux";
import { createApolloClient } from "./apollo/client";
import { createAppStore } from "./state/store";
import { loadWorkloadData } from "./platform/data";
import { setUpBenchmark } from "./workload/benchmark";
import { trackReactRoot } from "./workload/idle";
import { App } from "./App";
import { setSessionReader } from "./chat/tokenizer";

async function boot() {
  const data = await loadWorkloadData();
  setUpBenchmark(data);
  const store = createAppStore();
  setSessionReader(() => store.getState().session);
  const apollo = createApolloClient();
  const root = createRoot(document.getElementById("root")!);
  trackReactRoot(root);
  root.render(
    <ReduxProvider store={store}>
      <ApolloProvider client={apollo}>
        <App />
      </ApolloProvider>
    </ReduxProvider>,
  );
  await window.ssrWorkload!.whenIdle();
  (window as { ssrReady?: boolean }).ssrReady = true;
  window.dispatchEvent(new Event("ssr-ready"));
}

void boot();
