// Resolvers for the page's GraphQL operations. They serve the generated
// responses (data/generate-gql.mjs): one set per channel for channel-scoped
// operations and one global set for the others.
import timeline from "../../../data/timeline.json";
import type { GqlData } from "../platform/data";
import { registerGqlResolver } from "./fake-gql";

const channels = timeline.channels as Record<string, { roomId: string }>;
const loginByRoomId = new Map(Object.entries(channels).map(([login, c]) => [c.roomId, login]));

let currentLogin = Object.keys(channels)[0];

/** Called by the page that is being rendered, so operations without a login variable know their channel. */
export function setPageChannel(login: string): void {
  if (login in channels) currentLogin = login;
}

export function roomIdFor(login: string): string {
  return channels[login]?.roomId ?? "1";
}

function channelFromVariables(variables: Record<string, unknown>): string | null {
  for (const key of ["login", "channelLogin", "channel", "userLogin"]) {
    const v = variables[key];
    if (typeof v === "string" && v in channels) return v;
  }
  for (const key of ["channelID", "channelOwnerID"]) {
    const v = variables[key];
    if (typeof v === "string" && loginByRoomId.has(v)) return loginByRoomId.get(v)!;
  }
  const ids = variables.channelIDs;
  if (Array.isArray(ids) && typeof ids[0] === "string" && loginByRoomId.has(ids[0])) return loginByRoomId.get(ids[0])!;
  return null;
}

export function registerPageResolvers(gql: GqlData): void {
  const names = new Set<string>();
  for (const file of Object.values(gql.files)) for (const name of Object.keys(file)) names.add(name);
  for (const name of names) {
    registerGqlResolver(name, (variables) => {
      const login = channelFromVariables(variables) ?? currentLogin;
      return gql.files[login]?.[name] ?? gql.files.global[name] ?? gql.files[currentLogin]?.[name] ?? null;
    });
  }
}
