import IntlMessageFormat from "intl-messageformat";

const MESSAGES = {
  "viewers.count": "{count, number} {count, plural, one {viewer} other {viewers}}",
  "viewers.live": "{count, number} watching now",
  "followers.count": "{count, number} {count, plural, one {follower} other {followers}}",
  "about.title": "About {name}",
  "nav.forYou": "For You",
  "nav.recommended": "Recommended Channels",
  "nav.showMore": "Show More",
  "nav.showLess": "Show Less",
  "nav.collapse": "Collapse Side Nav",
  "nav.expand": "Expand Side Nav",
  "nav.browse": "Browse",
  "nav.login": "Log In",
  "nav.signup": "Sign Up",
  "nav.search": "Search",
  "channel.follow": "Follow",
  "channel.subscribe": "Subscribe",
  "channel.gift": "Gift a Sub",
  "channel.live": "LIVE",
  "channel.offline": "OFFLINE",
  "channel.title": "{name} - StreamingSite",
  "player.loading": "Loading",
  "player.play": "Play",
  "player.pause": "Pause",
  "player.mute": "Mute",
  "player.volume": "Volume",
  "player.settings": "Settings",
  "player.theatre": "Theatre Mode",
  "player.fullscreen": "Fullscreen",
  "player.clip": "Clip",
  "home.title": "StreamingSite - Live streams",
  "home.shelf.live": "Live channels we think you'll like",
  "home.shelf.categories": "Categories we think you'll like",
  "home.viewersOnCategory": "{count, number} {count, plural, one {viewer} other {viewers}}",
  "signup.banner": "Sign up to experience the best of {name}. Chat, follow or subscribe.",
} as const;

export type MessageId = keyof typeof MESSAGES;

const cache = new Map<string, IntlMessageFormat>();

export function t(id: MessageId, values?: Record<string, string | number>): string {
  let format = cache.get(id);
  if (!format) {
    format = new IntlMessageFormat(MESSAGES[id], "en-US");
    cache.set(id, format);
  }
  return format.format(values) as string;
}
