import { useMemo } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@apollo/client";
import { useDispatch, useSelector } from "react-redux";
import { SIDE_NAV } from "../apollo/documents";
import type { RootState } from "../state/store";
import { toggleRecommendedExpanded, toggleSideNav } from "../state/ui-slice";
import { compactCount } from "./format";
import { ICONS } from "./icons";
import { t } from "./i18n";
import { Avatar, ButtonIcon, CoreText, InjectLayout, Layout, SvgIcon, TextBlock, Tooltip } from "./primitives";

interface SideNavStream {
  id: string;
  viewersCount: number;
  hasHypeTrain: boolean;
  broadcaster: { id: string; login: string; displayName: string; profileImageURL: string };
  game: { id: string; displayName: string };
}

interface SideNavData {
  sideNav: { sections: { edges: { node: { id: string; content: { edges: { node: SideNavStream }[] } } }[] } };
}

function ChannelCard({ stream }: { stream: SideNavStream; collapsed: boolean }) {
  const { login, displayName, profileImageURL } = stream.broadcaster;
  return (
    <Layout className="side-nav-card" data-test-selector="side-nav-card">
      <Layout className="tw-tooltip-wrapper">
        <Tooltip label={displayName}>
          <Link className="side-nav-card__link tw-link-plain" to={`/${login}`} data-a-target="side-nav-channel" data-login={login}>
            <Layout display="flex" alignItems="center" fullWidth>
              <Layout className="side-nav-card__avatar" display="flex" alignItems="center">
                <Layout display="flex" as="figure" margin={0}>
                  <Layout className="tw-avatar-ring" display="flex" borderRadius="full">
                    <Layout display="flex" borderRadius="full" overflow="hidden">
                      <Avatar src={profileImageURL} size={30} alt={displayName} />
                    </Layout>
                  </Layout>
                </Layout>
              </Layout>
              <Layout className="side-nav-card__meta" display="flex" flexDirection="column" margin={{ left: 1 }}>
                <Layout className="side-nav-card__title" data-a-target="side-nav-title">
                  <Layout display="flex" alignItems="center">
                    <TextBlock fontSize={4} bold color="text-base" ellipsis>
                      {displayName}
                    </TextBlock>
                  </Layout>
                </Layout>
                <Layout className="side-nav-card__subtitle" data-a-target="side-nav-game-title">
                  <Layout display="flex" alignItems="center">
                    <TextBlock fontSize={4} color="text-alt-2" ellipsis>
                      {stream.game.displayName}
                    </TextBlock>
                  </Layout>
                </Layout>
              </Layout>
              <Layout className="side-nav-card__live-status" display="flex" alignItems="center" data-a-target="side-nav-live-status">
                <Layout className="side-nav-card__live-dot-wrapper" display="flex" alignItems="center">
                  <Layout className="side-nav-card__live-dot" />
                </Layout>
                <Layout margin={{ left: 0.5 }}>
                  <Layout display="flex" alignItems="center">
                    <TextBlock fontSize={4} color="text-base">
                      {compactCount(stream.viewersCount)}
                    </TextBlock>
                  </Layout>
                </Layout>
              </Layout>
            </Layout>
          </Link>
        </Tooltip>
      </Layout>
    </Layout>
  );
}

function Section({ title, streams, collapsed, action }: { title: string; streams: SideNavStream[]; collapsed: boolean; action?: React.ReactNode }) {
  return (
    <Layout className="side-nav-section" as="section" aria-label={title}>
      <Layout className="side-nav-header" display="flex" alignItems="center" justifyContent="space-between" padding={{ x: 1, y: 1 }}>
        <CoreText className="side-nav-header__title" as="h3" fontSize={4} bold transform="uppercase" color="text-alt-2">
          {title}
        </CoreText>
      </Layout>
      <Layout className="side-nav-section__list" role="group">
        {streams.map((s, i) => (
          <ChannelCard key={`${s.id}-${i}`} stream={s} collapsed={collapsed} />
        ))}
      </Layout>
      {action}
    </Layout>
  );
}

export function SideNav() {
  const dispatch = useDispatch();
  const collapsed = useSelector((s: RootState) => s.ui.sideNavCollapsed);
  const expanded = useSelector((s: RootState) => s.ui.recommendedExpanded);
  const { data } = useQuery<SideNavData>(SIDE_NAV, {
    variables: { input: { recommendationContext: { platform: "web" } }, creatorAnniversariesFeature: false, withFreeformTags: false },
  });
  const streams = useMemo(() => {
    const sections = data?.sideNav.sections.edges ?? [];
    return sections.flatMap((s) => s.node.content.edges.map((e) => e.node)).filter((n) => n.broadcaster);
  }, [data]);
  const shown = expanded ? streams : streams.slice(0, 13);
  return (
    <Layout as="nav" className={`side-nav ${collapsed ? "side-nav--collapsed" : "side-nav--expanded"}`} data-a-target="side-nav" aria-label="Primary Navigation">
      <Layout className="side-nav-header" display="flex" alignItems="center" justifyContent="space-between" padding={1}>
        <CoreText className="side-nav-header__title" as="h2" fontSize={5} bold>
          {t("nav.forYou")}
        </CoreText>
        <Tooltip label={collapsed ? t("nav.expand") : t("nav.collapse")}>
          <ButtonIcon label={collapsed ? t("nav.expand") : t("nav.collapse")} onClick={() => dispatch(toggleSideNav())} data-a-target="side-nav-arrow">
            <SvgIcon path={collapsed ? ICONS.expand : ICONS.collapse} />
          </ButtonIcon>
        </Tooltip>
      </Layout>
      <Layout className="side-nav-sections" display="flex" flexDirection="column">
        <Section
          title={t("nav.recommended")}
          streams={shown}
          collapsed={collapsed}
          action={
            streams.length > 13 || expanded ? (
              <Layout padding={{ x: 1, y: 1 }}>
                <InjectLayout>
                  <button className="side-nav__show-more" data-a-target="side-nav-show-more-button" onClick={() => dispatch(toggleRecommendedExpanded())}>
                    <CoreText fontSize={4} bold color="text-link">
                      {expanded ? t("nav.showLess") : t("nav.showMore")}
                    </CoreText>
                  </button>
                </InjectLayout>
              </Layout>
            ) : null
          }
        />
      </Layout>
    </Layout>
  );
}
