import { useState } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@apollo/client";
import { TOP_NAV_CURRENT_USER } from "../apollo/documents";
import { ICONS, type IconName } from "./icons";
import { t } from "./i18n";
import { ButtonIcon, CoreText, IconButton as PlainIconButton, InjectLayout, Layout, ScCoreButton, SvgIcon, TextBlock, Tooltip } from "./primitives";

function IconButton({ icon, label, appearance }: { icon: IconName; label: string; appearance?: "text" | "secondary" | "overlay" }) {
  return (
    <Tooltip label={label}>
      <ButtonIcon label={label} appearance={appearance ?? "text"}>
        <SvgIcon path={ICONS[icon]} />
      </ButtonIcon>
    </Tooltip>
  );
}

const SUGGESTIONS = ["Categories", "Channels", "Tags"];
const USER_MENU = ["Channel", "Creator Dashboard", "Drops & Rewards", "Subscriptions", "Settings", "Log Out"];

/** Menus that stay in the DOM while closed. */
function ClosedMenus() {
  return (
    <>
      <Layout className="top-nav__search-suggestions" role="listbox" hidden data-a-target="search-suggestions" display="none">
        {SUGGESTIONS.map((label) => (
          <Layout key={label} role="option" padding={{ x: 1, y: 0.5 }}>
            <Layout display="flex" alignItems="center" gap={1}>
              <SvgIcon path={ICONS.search} size={16} />
              <TextBlock fontSize={4}>{label}</TextBlock>
            </Layout>
          </Layout>
        ))}
      </Layout>
      <Layout className="top-nav__user-menu" role="menu" hidden data-a-target="user-menu" display="none">
        {USER_MENU.map((label) => (
          <Layout key={label} role="menuitem" padding={{ x: 1, y: 0.5 }}>
            <Layout as="a" display="flex" alignItems="center" gap={1}>
              <Layout display="flex">
                <SvgIcon path={ICONS.person} size={16} />
              </Layout>
              <TextBlock fontSize={4}>{label}</TextBlock>
            </Layout>
          </Layout>
        ))}
      </Layout>
    </>
  );
}

function NavLink({ to, children }: { to: string; children: string }) {
  return (
    <InjectLayout padding={{ x: 1 }}>
      <Link to={to} className="top-nav__link tw-link-plain" data-a-target="top-nav-link">
        <Layout display="flex" alignItems="center" height="3rem">
          <CoreText fontSize={5} bold>
            {children}
          </CoreText>
        </Layout>
      </Link>
    </InjectLayout>
  );
}

function SearchBox() {
  const [value, setValue] = useState("");
  return (
    <Layout className="top-nav__search-container" display="flex" justifyContent="center" padding={{ x: 1 }}>
      <Layout className="top-nav__search-box" role="search" as="form" onSubmit={(e) => e.preventDefault()}>
        <input
          className="top-nav__search-input"
          type="search"
          autoComplete="off"
          placeholder={t("nav.search")}
          aria-label={t("nav.search")}
          data-a-target="tw-input"
          value={value}
          onChange={(e) => setValue(e.target.value)}
        />
        <Tooltip label={t("nav.search")}>
          <button className="top-nav__search-button" type="submit" aria-label={t("nav.search")}>
            <Layout display="flex" alignItems="center" justifyContent="center">
              <SvgIcon path={ICONS.search} />
            </Layout>
          </button>
        </Tooltip>
      </Layout>
    </Layout>
  );
}

export function TopNav() {
  const { data } = useQuery(TOP_NAV_CURRENT_USER);
  const signedIn = Boolean(data?.currentUser);
  return (
    <Layout as="nav" className="top-nav" data-a-target="top-nav-container">
      <Layout className="top-nav__menu" display="flex" alignItems="center">
        <Link to="/" className="top-nav__logo" aria-label="StreamingSite home">
          <Layout display="flex" alignItems="center" padding={{ x: 0.5 }}>
            <SvgIcon path={ICONS.logo} size={30} />
          </Layout>
        </Link>
        <Layout display="flex" alignItems="center" margin={{ left: 1 }}>
          <NavLink to="/">{t("nav.browse")}</NavLink>
          <IconButton icon="menu" label="More" />
        </Layout>
      </Layout>
      <SearchBox />
      <Layout className="top-nav__menu top-nav__menu--right" display="flex" alignItems="center" justifyContent="flex-end">
        <PlainIconButton path={ICONS.gift} label="Prime Gaming" />
        <PlainIconButton path={ICONS.inbox} label="Notifications" />
        {signedIn ? null : (
          <>
            <InjectLayout margin={{ x: 0.5 }}>
              <ScCoreButton appearance="secondary" data-a-target="login-button">
                <Layout padding={{ x: 0.5 }}>{t("nav.login")}</Layout>
              </ScCoreButton>
            </InjectLayout>
            <InjectLayout margin={{ x: 0.5 }}>
              <ScCoreButton appearance="primary" data-a-target="signup-button">
                <Layout padding={{ x: 0.5 }}>{t("nav.signup")}</Layout>
              </ScCoreButton>
            </InjectLayout>
          </>
        )}
        <IconButton icon="user" label="User menu" />
      </Layout>
      <ClosedMenus />
    </Layout>
  );
}
