import type { TypePolicies } from "@apollo/client";

export const typePolicies: TypePolicies = {
  // The tag list is replaced as a whole by each operation that selects it.
  Stream: { fields: { freeformTags: { merge: false } } },
};

/**
 * Adds `merge: true` for the object fields that several operations select
 * with different sub-selections (data/generate-gql.mjs lists them), so that
 * one operation's write does not drop the other's fields.
 */
export function withGeneratedPolicies(policies: Record<string, string[]>): TypePolicies {
  const out: TypePolicies = { ...typePolicies };
  for (const [type, fields] of Object.entries(policies)) {
    out[type] = { ...out[type], fields: { ...out[type]?.fields, ...Object.fromEntries(fields.map((f) => [f, { merge: true }])) } };
  }
  return out;
}
