// A stand-in for Twitch's IRC WebSocket in benchmark mode. It has the
// WebSocket API the chat client uses, answers the handshake with the frames
// the real server sends (captured 2026-10-21), and delivers scheduled chat
// frames as `message` events, each in its own task, on the virtual clock.
import { setTimeout, clearTimeout } from "./timers";

const CONNECTING = 0;
const OPEN = 1;
const CLOSING = 2;
const CLOSED = 3;

export interface ScheduledFrame {
  /** Delay in ms from the start of the batch. */
  at: number;
  data: string;
}

export interface RoomInfo {
  login: string;
  roomId: string;
  roomState: string;
}

const sockets = new Set<FakeIrcSocket>();
const rooms = new Map<string, RoomInfo>();

/** Registers the ROOMSTATE the server sends when a client joins `login`. */
export function defineRoom(room: RoomInfo): void {
  rooms.set(room.login, room);
}

/** Schedules frames on every open socket that has joined `login`. */
export function playFrames(login: string, frames: readonly ScheduledFrame[]): void {
  for (const socket of sockets) {
    if (socket.joined.has(login)) socket.schedule(frames);
  }
}

type Listener = (event: Event) => void;

export class FakeIrcSocket extends EventTarget {
  static readonly CONNECTING = CONNECTING;
  static readonly OPEN = OPEN;
  static readonly CLOSING = CLOSING;
  static readonly CLOSED = CLOSED;
  readonly CONNECTING = CONNECTING;
  readonly OPEN = OPEN;
  readonly CLOSING = CLOSING;
  readonly CLOSED = CLOSED;

  readonly url: string;
  readonly protocol = "";
  readonly extensions = "";
  binaryType: BinaryType = "blob";
  bufferedAmount = 0;
  readyState = CONNECTING;
  onopen: Listener | null = null;
  onmessage: Listener | null = null;
  onerror: Listener | null = null;
  onclose: Listener | null = null;

  nick = "";
  readonly joined = new Set<string>();
  private readonly pending = new Set<number>();

  constructor(url: string | URL) {
    super();
    this.url = String(url);
    sockets.add(this);
    this.later(0, () => {
      this.readyState = OPEN;
      this.fire(new Event("open"), this.onopen);
    });
  }

  private later(ms: number, fn: () => void): void {
    const id = setTimeout(() => {
      this.pending.delete(id);
      if (this.readyState !== CLOSED) fn();
    }, ms);
    this.pending.add(id);
  }

  private fire(event: Event, handler: Listener | null): void {
    handler?.call(this, event);
    this.dispatchEvent(event);
  }

  private deliver(data: string): void {
    if (this.readyState !== OPEN) return;
    this.fire(new MessageEvent("message", { data }), this.onmessage);
  }

  /** Delivers `data` in a task of its own after the frames already queued. */
  reply(data: string): void {
    this.later(0, () => this.deliver(data));
  }

  schedule(frames: readonly ScheduledFrame[]): void {
    for (const frame of frames) this.later(frame.at, () => this.deliver(frame.data));
  }

  send(data: string): void {
    if (this.readyState !== OPEN) throw new DOMException("WebSocket is not open", "InvalidStateError");
    for (const line of data.split("\r\n")) {
      if (line) this.handleClientLine(line);
    }
  }

  private handleClientLine(line: string): void {
    const space = line.indexOf(" ");
    const command = space === -1 ? line : line.slice(0, space);
    const rest = space === -1 ? "" : line.slice(space + 1);
    switch (command) {
      case "CAP":
        this.reply(`:tmi.twitch.tv CAP * ACK :${rest.replace(/^REQ :/, "")}\r\n`);
        break;
      case "NICK": {
        const n = (this.nick = rest.trim());
        this.reply(
          `:tmi.twitch.tv 001 ${n} :Welcome, GLHF!\r\n:tmi.twitch.tv 002 ${n} :Your host is tmi.twitch.tv\r\n` +
            `:tmi.twitch.tv 003 ${n} :This server is rather new\r\n:tmi.twitch.tv 004 ${n} :-\r\n` +
            `:tmi.twitch.tv 375 ${n} :-\r\n:tmi.twitch.tv 372 ${n} :You are in a maze of twisty passages, all alike.\r\n` +
            `:tmi.twitch.tv 376 ${n} :>\r\n`,
        );
        break;
      }
      case "JOIN":
        for (const channel of rest.split(",")) this.join(channel.trim().replace(/^#/, ""));
        break;
      case "PART": {
        const login = rest.trim().replace(/^#/, "");
        this.joined.delete(login);
        const n = this.nick;
        this.reply(`:${n}!${n}@${n}.tmi.twitch.tv PART #${login}\r\n`);
        break;
      }
      case "PING":
        this.reply(`:tmi.twitch.tv PONG tmi.twitch.tv ${rest}\r\n`);
        break;
      default:
        break;
    }
  }

  private join(login: string): void {
    const n = this.nick;
    const room = rooms.get(login);
    this.joined.add(login);
    const roomState = room ? `${room.roomState} :tmi.twitch.tv ROOMSTATE #${login}\r\n` : "";
    this.reply(`:${n}!${n}@${n}.tmi.twitch.tv JOIN #${login}\r\n${roomState}`);
    this.reply(`:${n}.tmi.twitch.tv 353 ${n} = #${login} :${n}\r\n:${n}.tmi.twitch.tv 366 ${n} #${login} :End of /NAMES list\r\n`);
  }

  close(code = 1000, reason = ""): void {
    if (this.readyState === CLOSED) return;
    for (const id of this.pending) clearTimeout(id);
    this.pending.clear();
    this.readyState = CLOSED;
    sockets.delete(this);
    this.fire(new CloseEvent("close", { code, reason, wasClean: true }), this.onclose);
  }
}

/** Opens a socket to `url`: the fake one in benchmark mode, a real one otherwise. */
export function openIrcSocket(url: string, fake: boolean): WebSocket {
  return fake ? (new FakeIrcSocket(url) as unknown as WebSocket) : new WebSocket(url);
}
