// Side nav UI state in the Redux store, written with immer as on the site.
import { produce } from "immer";
import type { AnyAction } from "redux";

export interface UiState {
  sideNavCollapsed: boolean;
  recommendedExpanded: boolean;
}

const initial: UiState = { sideNavCollapsed: false, recommendedExpanded: false };

export const toggleSideNav = () => ({ type: "ui/toggleSideNav" });
export const toggleRecommendedExpanded = () => ({ type: "ui/toggleRecommendedExpanded" });

export function ui(state: UiState = initial, action: AnyAction): UiState {
  return produce(state, (draft) => {
    switch (action.type) {
      case "ui/toggleSideNav":
        draft.sideNavCollapsed = !draft.sideNavCollapsed;
        break;
      case "ui/toggleRecommendedExpanded":
        draft.recommendedExpanded = !draft.recommendedExpanded;
        break;
    }
  });
}
