// The app's timers. App code imports setTimeout, setInterval and now() from
// here instead of using the globals.
//
// In a normal tab these are the browser's timers. In benchmark mode they run
// on a virtual clock: time only moves when a benchmark step calls advance(),
// and each due callback then runs in its own task, in timestamp order. This
// keeps the work of Twitch-style fixed-delay timers (the 200 ms chat flush,
// the 1 s tickers) inside a step without measuring the idle time between
// them.

type Callback = () => void;

interface Timer {
  id: number;
  due: number;
  seq: number;
  interval: number | null;
  callback: Callback;
}

/** 2026-10-21T20:00:00Z, so that generated timestamps are reproducible. */
const VIRTUAL_EPOCH = 1792612800000;

let virtual = false;
let virtualNow = VIRTUAL_EPOCH;
let nextId = 1;
let nextSeq = 0;
const timers = new Map<number, Timer>();
const idleWaiters: Callback[] = [];
let advancing = false;

export function enableVirtualTime(): void {
  virtual = true;
}

export function isVirtualTime(): boolean {
  return virtual;
}

export function now(): number {
  return virtual ? virtualNow : Date.now();
}

function addTimer(callback: Callback, ms: number, interval: boolean): number {
  const delay = Math.max(0, ms || 0);
  const timer: Timer = { id: nextId++, due: virtualNow + delay, seq: nextSeq++, interval: interval ? Math.max(1, delay) : null, callback };
  timers.set(timer.id, timer);
  if (!advancing) void runDue(virtualNow);
  return timer.id;
}

function removeTimer(id: number | undefined): void {
  if (id !== undefined) timers.delete(id);
}

const nativeSetTimeout = globalThis.setTimeout.bind(globalThis);
const nativeClearTimeout = globalThis.clearTimeout.bind(globalThis);
const nativeSetInterval = globalThis.setInterval.bind(globalThis);
const nativeClearInterval = globalThis.clearInterval.bind(globalThis);

export function setTimeout(callback: Callback, ms = 0): number {
  return virtual ? addTimer(callback, ms, false) : (nativeSetTimeout(callback, ms) as unknown as number);
}

export function clearTimeout(id: number | undefined): void {
  if (virtual) removeTimer(id);
  else nativeClearTimeout(id);
}

export function setInterval(callback: Callback, ms: number): number {
  return virtual ? addTimer(callback, ms, true) : (nativeSetInterval(callback, ms) as unknown as number);
}

export function clearInterval(id: number | undefined): void {
  if (virtual) removeTimer(id);
  else nativeClearInterval(id);
}

const channel = typeof MessageChannel === "function" ? new MessageChannel() : null;
const taskQueue: Callback[] = [];
if (channel) channel.port1.onmessage = () => taskQueue.shift()?.();

/** Resolves in a new task, after the tasks that are already queued. */
export function nextTask(): Promise<void> {
  return new Promise((resolve) => {
    taskQueue.push(resolve);
    channel!.port2.postMessage(null);
  });
}

function earliestDue(limit: number): Timer | null {
  let best: Timer | null = null;
  for (const t of timers.values()) {
    if (t.due > limit) continue;
    if (!best || t.due < best.due || (t.due === best.due && t.seq < best.seq)) best = t;
  }
  return best;
}

async function runDue(limit: number): Promise<void> {
  if (advancing) return;
  advancing = true;
  try {
    for (;;) {
      await nextTask();
      const timer = earliestDue(limit);
      if (!timer) break;
      virtualNow = Math.max(virtualNow, timer.due);
      if (timer.interval === null) timers.delete(timer.id);
      else {
        timer.due += timer.interval;
        timer.seq = nextSeq++;
      }
      try {
        timer.callback();
      } catch (e) {
        reportError(e);
      }
    }
  } finally {
    advancing = false;
  }
  if (earliestDue(virtualNow)) void runDue(virtualNow);
  else idleWaiters.splice(0).forEach((w) => w());
}

/**
 * Moves virtual time forward by `ms`, running every timer that falls due on
 * the way, each in its own task. Resolves when the clock has reached the end
 * and no timer is due.
 */
export async function advance(ms: number): Promise<void> {
  while (advancing) await whenTimersIdle();
  const target = virtualNow + ms;
  await runDue(target);
  virtualNow = target;
  await whenTimersIdle();
}

/** Resolves once no timer is due at the current virtual time. */
export function whenTimersIdle(): Promise<void> {
  if (!advancing && !earliestDue(virtualNow)) return Promise.resolve();
  return new Promise((resolve) => idleWaiters.push(resolve));
}

/** Timers that are due at the current virtual time (delay-0 work not yet run). */
export function hasDueTimers(): boolean {
  return advancing || earliestDue(virtualNow) !== null;
}
