// The GraphQL documents of the queries that drive visible UI. Operation
// names are the ones the real site sends. Operations that only feed
// background state are generated from the schema (BackgroundQueries.tsx).
import { gql } from "@apollo/client";

export const TOP_NAV_CURRENT_USER = gql`
  query TopNav_CurrentUser {
    currentUser {
      id
      login
      displayName
      profileImageURL(width: 50)
    }
    requestInfo {
      countryCode
    }
  }
`;

export const SIDE_NAV = gql`
  query SideNav($input: SideNavInput!, $creatorAnniversariesFeature: Boolean!, $withFreeformTags: Boolean!) {
    sideNav {
      sections {
        edges {
          cursor
          node {
            id
            title {
              fallbackLocalizedTitle
              key
            }
            content {
              edges {
                cursor
                node {
                  ... on Stream {
                    id
                    type
                    viewersCount
                    hasHypeTrain
                    broadcaster {
                      id
                      login
                      displayName
                      profileImageURL(width: 70)
                      broadcastSettings {
                        id
                        title
                      }
                    }
                    game {
                      id
                      slug
                      displayName
                      name
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
`;

export const CHANNEL_SHELL = gql`
  query ChannelShell($login: String!) {
    userOrError(login: $login) {
      ... on User {
        id
        login
        displayName
        primaryColorHex
        profileImageURL(width: 70)
        bannerImageURL
        stream {
          id
          viewersCount
        }
      }
    }
  }
`;

export const STREAM_METADATA = gql`
  query StreamMetadata($channelLogin: String!) {
    user(login: $channelLogin) {
      id
      displayName
      primaryColorHex
      roles {
        isPartner
        isParticipatingDJ
      }
      profileImageURL(width: 70)
      lastBroadcast {
        id
        title
      }
      stream {
        id
        type
        createdAt
        game {
          id
          slug
          name
        }
      }
    }
  }
`;

export const USE_VIEW_COUNT = gql`
  query UseViewCount($channelLogin: String!) {
    user(login: $channelLogin) {
      id
      stream {
        id
        viewersCount
      }
    }
  }
`;

export const USE_LIVE = gql`
  query UseLive($channelLogin: String!) {
    user(login: $channelLogin) {
      id
      login
      stream {
        id
        createdAt
      }
    }
  }
`;

export const ABOUT_PANEL = gql`
  query ChannelRoot_AboutPanel($channelLogin: String!, $skipSchedule: Boolean!) {
    user(login: $channelLogin) {
      id
      description
      displayName
      primaryColorHex
      profileImageURL(width: 70)
      followers {
        totalCount
      }
      roles {
        isPartner
        isAffiliate
      }
      channel {
        id
        socialMedias {
          id
          name
          title
          url
        }
      }
      lastBroadcast {
        id
        game {
          id
          displayName
        }
      }
    }
  }
`;

export const SUBSCRIBE_BUTTON = gql`
  query ChannelPage_SubscribeButton_User($login: String!, $includeExpiredDunning: Boolean!) {
    user(login: $login) {
      id
      displayName
      subscriptionProducts {
        id
        name
        tier
        hasAdFree
      }
    }
  }
`;

export const REALTIME_STREAM_TAG_LIST = gql`
  query RealtimeStreamTagList($channelLogin: String!) {
    user(login: $channelLogin) {
      id
      stream {
        id
        freeformTags {
          id
          name
        }
      }
    }
  }
`;

export const SHELVES = gql`
  query Shelves($imageWidth: Int, $itemsPerRow: Int, $platform: String!, $limit: Int, $requestID: String!, $context: String) {
    shelves(itemsPerRow: $itemsPerRow, platform: $platform, limit: $limit, requestID: $requestID, context: $context) {
      edges {
        node {
          id
          title {
            key
            fallbackLocalizedTitle
          }
          content {
            edges {
              cursor
              node {
                __typename
                ... on Stream {
                  id
                  viewersCount
                  previewImageURL
                  type
                  createdAt
                  broadcaster {
                    id
                    login
                    displayName
                    profileImageURL(width: 70)
                    broadcastSettings {
                      id
                      title
                    }
                    roles {
                      isPartner
                    }
                  }
                  game {
                    id
                    categorySlug
                    name
                    displayName
                  }
                  freeformTags {
                    id
                    name
                  }
                }
                ... on Game {
                  id
                  categorySlug
                  name
                  displayName
                  boxArtURL
                  viewersCount
                }
              }
            }
          }
        }
      }
    }
  }
`;

/** Names of the operations above: the background waves skip them, the components issue them. */
export const UI_OPERATIONS = new Set([
  "TopNav_CurrentUser",
  "SideNav",
  "ChannelShell",
  "StreamMetadata",
  "UseViewCount",
  "UseLive",
  "ChannelRoot_AboutPanel",
  "ChannelPage_SubscribeButton_User",
  "RealtimeStreamTagList",
  "Shelves",
]);
